import{aB as o,i as t,o as d,b3 as a}from"./chunks/framework.CJ7iKQOZ.js";const u=JSON.parse('{"title":"局限性","description":"","frontmatter":{"title":"局限性"},"headers":[],"relativePath":"limit.md","filePath":"limit.md"}'),c={name:"limit.md"};function l(i,e,n,s,p,r){return d(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="局限性" tabindex="-1">局限性 <a class="header-anchor" href="#局限性" aria-label="Permalink to &quot;局限性&quot;">​</a></h1><p>由于编辑器是基于<code>web components</code>实现的，因此一些常见的问题同时也是存在的。</p><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>大部分组件库一旦涉及到弹窗、悬浮框之类脱离文档流的组件，会直接插入到<code>document.body</code>中。编辑器的样式挂在<code>shadow dom</code>里，<code>shadow dom</code>外的元素拿不到，照理会出现样式丢失。</p><p>编辑器对此做了处理：element-plus 的主题会同时注入到两处——</p><ul><li><code>shadow dom</code>：编辑器内部以及渲染在编辑器里的业务组件；</li><li><code>document.head</code>：兜住 teleport 到<code>document.body</code>的弹层（<code>ElDialog</code>、<code>ElSelect</code> 下拉、<code>ElTooltip</code> 等）。</li></ul><p>两处用的是同一份样式（命名空间都是<code>mpd</code>），因此业务组件只要按正常方式使用 element-plus（依赖全局注册、不额外配置）即可，弹层也有样式。</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>业务组件渲染在编辑器里，使用的是编辑器提供的 element-plus 实例（模块联邦共享），命名空间、locale 都跟着编辑器走，不需要也不应该再单独引入一份 element-plus。</p></div><h2 id="弹窗层级" tabindex="-1">弹窗层级 <a class="header-anchor" href="#弹窗层级" aria-label="Permalink to &quot;弹窗层级&quot;">​</a></h2><p>常规的组件库中，弹窗默认插入到<code>document.body</code>中，因此往往不需要刻意调整，但是在<code>web components</code>中，编辑器自身的层级与宿主的其它浮层是各自独立的：如果宿主环境同时打开了弹窗或存在蒙层，仍然可能覆盖到编辑器之上。这类层级问题需要宿主自行协调 z-index。</p>',10)])])}const h=o(c,[["render",l]]);export{u as __pageData,h as default};
